 public function enqueue(MarketingProject $p,string $request,string $content,string $filmId,bool $allowHead=false):array {
  abort_unless(self::enabled()&&app(MarketingConversation::class)->available($p),403,'剪辑助手目前仅对已开放的本地测试启用，不使用有次数限制的旧预算授权。');
  return DB::transaction(function()use($p,$request,$content,$filmId,$allowHead){
   $p=MarketingProject::where('owner_id',$p->owner_id)->lockForUpdate()->findOrFail($p->id);
   $old=Message::where('project_id',$p->id)->where('request_id',$request)->where('role','user')->first();
   if($old){abort_unless($old->content===$content&&($old->context['film_id']??'')===$filmId&&(bool)($old->context['head_trim_requested']??false)===$allowHead,409);return ['queued'=>false];}
   abort_if(Message::where('project_id',$p->id)->where('status','pending')->exists(),409,'上一条消息仍在处理中，请重新读取进度。');
   $film=MarketingVideoFilm::where('project_id',$p->id)->where('owner_id',$p->owner_id)->where('status','completed')->findOrFail($filmId);app(MarketingWorkspaceFilm::class)->assertCurrent($film);app(MarketingVideoFiles::class)->file($film->output_path,$film->output_sha256);
   $ctx=['kind'=>'editing','film_id'=>$film->id,'film_sha256'=>$film->output_sha256,'stage'=>'queued','heartbeat'=>now()->toIso8601String(),'head_trim_requested'=>$allowHead];
