   Message::create($data+['role'=>'user','sequence'=>$seq,'content'=>$content,'status'=>'completed']);$reply=Message::create($data+['role'=>'assistant','sequence'=>$seq+1,'content'=>'AI is thinking… 正在检查所选成片与实际素材。','status'=>'pending']);ProcessMarketingEditingConversation::dispatch($reply->id);return ['queued'=>true];
  });
 }
