   if(array_key_exists('information_cards',$data)&&$data['information_cards']!==null){$ctx=$m->fresh()->context;$ctx['information_candidate']=$data['information_cards'];$m->update(['context'=>$ctx]);$ctx['information_proposal']=app(MarketingInformationDiscussion::class)->suggestion($p,$film,$data['information_cards'],$user->content);$m->update(['context'=>$ctx]);$data['proposal']=null;$data['packaging']=null;$data['subtitles']=null;$data['handoff_category']='none';}
