 public function markUnknown(string $id):void{$m=Message::find($id);if($m&&$m->status==='pending'){$m->update(['role'=>'system','status'=>'completed','content'=>'处理等待已结束，外部结果可能未知。原片保留，未自动重试；可核对记录后明确重新分析。']);$this->stage($m,'unknown');if($m->run_id)MarketingAiRun::whereKey($m->run_id)->where('status','running')->update(['status'=>'unknown']);$a=Analysis::where('project_id',$m->project_id)->find($m->context['active_analysis_id']??null);if($a&&$a->status==='analyzing'){$a->update(['status'=>$a->run_id?'unknown':'failed','error_message'=>'分析处理中断；未自动重试，原有记录保留。']);if($a->run_id)MarketingAiRun::whereKey($a->run_id)->where('status','running')->update(['status'=>'unknown']);}}}
 public function retry(string $project,int $owner,string $messageId,string $requestId):string {
  return DB::transaction(function()use($project,$owner,$messageId,$requestId){$p=MarketingProject::where('owner_id',$owner)->lockForUpdate()->findOrFail($project);$old=Message::where('project_id',$project)->where('request_id',$requestId)->where('role','user')->first();if($old)return $old->context['film_id'];$m=Message::where('project_id',$project)->where('actor_id',$owner)->lockForUpdate()->findOrFail($messageId);abort_unless(($m->context['kind']??'')==='editing',409);
   if($m->status==='pending'){abort_unless($m->updated_at->lte(now()->subMinutes(17)),409,'任务仍在处理中，不能重复分析。');$this->markUnknown($m->id);$m->refresh();}
   abort_unless(in_array($m->context['stage']??'', ['blocked','unknown']),409);[$p,$film]=$this->base($m);
   if($id=$m->context['active_analysis_id']??null){$a=Analysis::where('project_id',$project)->where('owner_id',$owner)->lockForUpdate()->findOrFail($id);abort_unless(in_array($a->status,['completed','failed','blocked','unknown']),409,'分析仍在处理，请重新读取。');if($a->status!=='completed'){$history=$a->usage['attempts']??[];$history[]=['run_id'=>$a->run_id,'status'=>$a->status,'ended_at'=>now()->toIso8601String()];$a->update(['status'=>'queued','run_id'=>null,'started_at'=>null,'error_message'=>null,'usage'=>['attempts'=>$history]]);}}
   $this->enqueue($p,$requestId,'重新分析现有成片并提出安全剪辑建议；保留完整口播与结尾阅读时间，不生成新画面或声音。',$film->id,(bool)($m->context['head_trim_requested']??false));return $film->id;
  });
 }
